import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const FotoDesfoqueDactilografia: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const dur = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const params = anim.params ?? {};
  const src = String(params.src ?? "");
  const text = String(anim.text ?? "").trim().toUpperCase();
  const blurParam = Number(params.blur);
  const maxBlur = (Number.isFinite(blurParam) && blurParam >= 0 ? blurParam : 14) * (frame.width / 1080);
  const cpsParam = Number(params.charsPerSecond);
  const cpsWanted = Number.isFinite(cpsParam) && cpsParam > 0 ? cpsParam : 14;

  // Image: fade in, slow push-in, then blur ramps up as the typing begins.
  const imgOpacity = interpolate(f, [0, 8], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const scale = interpolate(f, [0, dur], [1, 1.06], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const blurStart = Math.round(dur * 0.15);
  const blurEnd = Math.max(blurStart + 1, Math.round(dur * 0.45));
  const blur = interpolate(f, [blurStart, blurEnd], [0, maxBlur], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });
  const scrim = interpolate(f, [blurStart, blurEnd], [0, 0.35], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Typing: starts at 30% and is guaranteed to finish by 80% of the layer.
  const typeStart = Math.round(dur * 0.3);
  const typeWindowSec = Math.max(0.1, (dur * 0.5) / fps);
  const cps = Math.max(cpsWanted, text.length / typeWindowSec);
  const typed = Math.max(0, Math.min(text.length, Math.floor(((f - typeStart) / fps) * cps)));
  const caretOn = f >= typeStart && Math.floor(f / Math.max(1, Math.round(fps * 0.25))) % 2 === 0;

  // One line, never wrapped: shrink the font until the full text fits the width.
  const base = format === "portrait" ? frame.width * 0.12 : frame.height * 0.13;
  const maxWidth = frame.width * 0.86;
  const fontSize = text.length > 0 ? Math.min(base, maxWidth / (text.length * 0.72)) : base;

  const textColor = src ? "rgba(255,255,255,1)" : dark ? COLORS.textOnDark : COLORS.textOnLight;
  const inset = Math.round(Math.min(frame.width, frame.height) * 0.08);

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display }}>
      {src ? (
        <AbsoluteFill style={{ overflow: "hidden", opacity: imgOpacity }}>
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              transform: `scale(${scale})`,
              filter: `blur(${blur}px)`,
            }}
          />
          <AbsoluteFill style={{ backgroundColor: `rgba(0,0,0,${scrim})` }} />
        </AbsoluteFill>
      ) : (
        <div
          style={{
            position: "absolute",
            left: inset,
            top: inset,
            right: inset,
            bottom: inset,
            border: `${Math.max(2, Math.round(frame.width / 400))}px dashed rgba(255,255,255,0.25)`,
            backgroundColor: "rgba(255,255,255,0.06)",
            opacity: imgOpacity,
          }}
        />
      )}

      {text.length > 0 ? (
        <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
          <div
            style={{
              whiteSpace: "nowrap",
              fontSize,
              fontWeight: FONTS.displayWeight,
              letterSpacing: "0.02em",
              lineHeight: 1.1,
              color: textColor,
              textAlign: "center",
            }}
          >
            <span>{text.slice(0, typed)}</span>
            <span
              style={{
                display: "inline-block",
                width: "0.08em",
                height: "0.9em",
                marginLeft: "0.04em",
                marginRight: "-0.12em",
                verticalAlign: "-0.05em",
                backgroundColor: COLORS.tealBright,
                opacity: caretOn && typed < text.length + 1 ? 1 : 0,
              }}
            />
            {/* Untyped remainder keeps its space so the line stays centred while typing. */}
            <span style={{ color: "transparent" }}>{text.slice(typed)}</span>
          </div>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export default FotoDesfoqueDactilografia;

