import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, spring, Easing } from "remotion";
import { COLORS, FONTS, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const ImagemDesfoqueTitulo: React.FC<PrimitiveProps> = ({ anim, fps, dark, format, frame }) => {
  const f = useCurrentFrame();
  const dur = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const src = String(anim.params?.src ?? "");
  const text = String(anim.text ?? "").trim();
  const blurParam = Number(anim.params?.blur);
  const dimParam = Number(anim.params?.dim);
  const blurMax = (Number.isFinite(blurParam) ? Math.max(0, blurParam) : 16) * (frame.width / 1080);
  const dimMax = Number.isFinite(dimParam) ? Math.min(0.8, Math.max(0, dimParam)) : 0.4;

  const blurStart = Math.round(dur * 0.22);
  const blurEnd = Math.max(blurStart + 1, Math.round(dur * 0.55));
  const blurT = interpolate(f, [blurStart, blurEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.cubic),
  });
  const blur = blurT * blurMax;
  const dim = blurT * dimMax;
  const zoom = interpolate(f, [0, dur], [1.12, 1.04], { extrapolateRight: "clamp" });

  const textStart = Math.round(dur * 0.32);
  const reveal = spring({ frame: f - textStart, fps, config: { damping: 200 }, durationInFrames: Math.max(1, Math.round(fps * 0.8)) });

  const textColor = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const base =
    format === "landscape" ? frame.height * 0.13 : format === "half" ? frame.height * 0.12 : frame.width * 0.11;
  const len = Math.max(1, text.length);
  const perLine = format === "landscape" ? 28 : 16;
  const fontSize = base * Math.min(1, Math.sqrt(perLine / len) * 1.15);

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, alignItems: "center", justifyContent: "center" }}>
      {src ? (
        <AbsoluteFill style={{ overflow: "hidden" }}>
          <Img
            src={src}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              transform: `scale(${zoom})`,
              filter: `blur(${blur}px)`,
            }}
          />
          <AbsoluteFill style={{ backgroundColor: `rgba(0,0,0,${dim})` }} />
        </AbsoluteFill>
      ) : (
        <div
          style={{
            position: "absolute",
            inset: "6%",
            borderRadius: 0,
            border: `${Math.max(2, frame.width * 0.003)}px dashed ${COLORS.mutedOnLight}66`,
            backgroundColor: "rgba(255,255,255,0.06)",
            filter: `blur(${blur * 0.3}px)`,
          }}
        />
      )}
      {text ? (
        <div
          style={{
            position: "relative",
            maxWidth: format === "landscape" ? "78%" : "86%",
            textAlign: "center",
            color: textColor,
            fontSize,
            fontWeight: FONTS.displayWeight,
            fontStyle: "italic",
            textTransform: "uppercase",
            lineHeight: 0.98,
            overflowWrap: "break-word",
            textShadow: ENGRAVE_SHADOW,
            opacity: reveal,
            letterSpacing: `${interpolate(reveal, [0, 1], [0.12, 0.01])}em`,
            transform: `translateY(${interpolate(reveal, [0, 1], [frame.height * 0.03, 0])}px) scale(${interpolate(reveal, [0, 1], [0.94, 1])})`,
          }}
        >
          {text}
        </div>
      ) : null}
    </AbsoluteFill>
  );
};

export default ImagemDesfoqueTitulo;
